+ constructor(version = '1') {
+ this.version = version;
+ }
+
+ getVersion(): string {
+ return this.version;
+ }
+
+ getHeader(): string {
+ return `// Snapshot v${this.version}`;
+ }
+
+ async readSnapshotFile(filepath: string): Promise<string> {
+ try {
