+ // rare (would require two endpoints whose method+path collapse to
+ // the same identifier) but cheap to guard against.
+ let n = 2;
+ while (seen.has(`${name}_${n}`)) n += 1;
+ name = `${name}_${n}`;
+ }
+ seen.add(name);
+ registered.push(name);
+
+ server.registerTool(
+ name,
