+ FontFamily::Times => Font::TimesRoman,
+ FontFamily::Courier => Font::Courier,
+ }
+ }
+
+ pub fn bold(self) -> Font {
+ match self {
+ FontFamily::Helvetica => Font::HelveticaBold,
+ FontFamily::Times => Font::TimesBold,
+ FontFamily::Courier => Font::CourierBold,
+ }
