+ public static bool HasText(this TokenType type)
+ {
+ return TokenTexts.ContainsKey(type);
+ }
+
+ public static string ToText(this TokenType type)
+ {
+ string value;
+ TokenTexts.TryGetValue(type, out value);
+ return value;
+ }
+ }
